package com.bank.fraud;

import java.util.HashMap;
import java.util.Map;

class FraudNameChecker {

    // Frequency count: O(n) time. +1 for first string, -1 for second.
    boolean areAnagrams(String a, String b) {
        if (a == null || b == null) return false;
        String na = normalise(a);
        String nb = normalise(b);
        if (na.length() != nb.length()) return false;   // quick reject

        Map<Character, Integer> freq = new HashMap<>();
        for (char c : na.toCharArray()) {
            freq.merge(c, 1, Integer::sum);              // count up
        }
        for (char c : nb.toCharArray()) {
            int remaining = freq.getOrDefault(c, 0) - 1; // count down
            if (remaining < 0) return false;             // more of c in b than a
            freq.put(c, remaining);
        }
        // all counts must be zero now (lengths equal + no negatives → guaranteed)
        return true;
    }

    private String normalise(String s) {
        return s.toLowerCase().replaceAll("\\s+", "");   // lowercase, drop spaces
    }
}
